#include <string>
#include <cstdint>

// Simulating the function signature
void PutVarint32(std::string* dst, uint32_t v) {
    // Varint32 encoding: each byte uses 7 bits for value, 1 bit as continuation flag
    // MSB = 1 means more bytes follow, MSB = 0 means last byte
    while (v >= 128) {
        // Set the continuation bit (MSB = 1) and append the 7-bit chunk
        dst->push_back(static_cast<char>((v & 0x7F) | 0x80));
        v >>= 7;
    }
    // Append the last byte (MSB = 0)
    dst->push_back(static_cast<char>(v & 0x7F));
}

// Test the implementation
#include <iostream>
int main() {
    std::string s;

    // Test various values
    PutVarint32(&s, 0);      // Single byte: 0x00
    PutVarint32(&s, 1);      // Single byte: 0x01
    PutVarint32(&s, 127);    // Single byte: 0x7F
    PutVarint32(&s, 128);    // Two bytes: 0x80 0x01
    PutVarint32(&s, 300);    // Two bytes: 0xAC 0x02
    PutVarint32(&s, 16384);  // Three bytes: 0x80 0x80 0x01

    // Expected encodings:
    // 0 -> 00
    // 1 -> 01
    // 127 -> 7F
    // 128 -> 80 01
    // 300 -> AC 02
    // 16384 -> 80 80 01

    std::cout << "Encoded " << s.size() << " bytes" << std::endl;

    // Verify by checking byte values
    std::cout << "Byte 0 (expect 0): " << (int)(unsigned char)s[0] << std::endl;
