void PutVarint32(std::string* dst, uint32_t v) {
    while (v >= 128) {
        dst->push_back(static_cast<char>((v & 0x7F) | 0x80));
        v >>= 7;
    }
    dst->push_back(static_cast<char>(v & 0x7F));
}

PutVarint32(&test_dst, 0);
PutVarint32(&test_dst, 1);
PutVarint32(&test_dst, 127);
PutVarint32(&test_dst, 128);
PutVarint32(&test_dst, 300);
PutVarint32(&test_dst, 16384);

int result = (test_dst[0] == 0) && (test_dst[1] == 1) && (test_dst[2] == 127) && 
           (test_dst[3] == (char)128) && (test_dst[4] == 1) && (test_dst[5] == (char)172) && 
           (test_dst[6] == 2) && (test_dst[7] == (char)128) && (test_dst[8] == (char)128) && 
           (test_dst[9] == 1) ? 0 : 1;

int main() { return result; }
